with ins as (
  insert into public.problems (slug, title, description, difficulty, topic, hints, constraints, solution_explanation,
                               time_complexity, space_complexity, is_premium, order_index, starter_code, judge_config)
  select E'binary-search-index', E'Binary Search', E'nums is sorted in ascending order and has no duplicates. Return the index of target, or -1 if it is not present. Aim for O(log n).', E'easy', E'Binary Search', array[E'Look at the middle element first.',E'Each comparison lets you discard half of the remaining range.']::text[], E'1 <= nums.length <= 10^4\nAll values are distinct and sorted ascending.',
         E'Keep a range [l, r]. Compare the middle value with target: equal returns the index, smaller moves l past the middle, bigger moves r before it. The range halves each step.', E'O(log n)', E'O(1)', false,
         (select coalesce(max(order_index), 0) + 1 from public.problems), E'{"javascript": "/**\\n * @param {number[]} nums\\n * @param {number} target\\n * @return {number}\\n */\\nfunction search(nums, target) {\\n  \\n}\\n", "python": "class Solution:\\n    def search(self, nums, target):\\n        pass\\n", "java": "class Solution {\\n    public int search(int[] nums, int target) {\\n        \\n    }\\n}\\n", "cpp": "class Solution {\\npublic:\\n    int search(vector<int>& nums, int target) {\\n        \\n    }\\n};\\n"}'::jsonb,
         jsonb_build_object('compare', E'exact')
   where not exists (select 1 from public.problems where slug = E'binary-search-index')
  returning id)
insert into public.problem_test_cases (problem_id, input, expected_output, is_sample, explanation, sort_order)
